# ---------------------------------------------------------------------------
# Polynomial evaluation helpers
# ---------------------------------------------------------------------------

def poly_eval(coeffs, t):
    """Evaluate degree-7 polynomial at physical time t."""
    result = 0.0
    tp = 1.0
    for c in coeffs:
        result += c * tp
        tp *= t
    return result


def poly_deriv(coeffs, t):
    """First derivative (velocity) at physical time t."""
    result = 0.0
    for k in range(1, len(coeffs)):
        result += k * coeffs[k] * (t ** (k - 1))
    return result


def poly_deriv2(coeffs, t):
    """Second derivative (acceleration) at physical time t."""
    result = 0.0
    for k in range(2, len(coeffs)):
        result += k * (k - 1) * coeffs[k] * (t ** (k - 2))
    return result


def eval_trajectory(traj, pts_per_seg=50, speed_scale=1.0):
    """
    Evaluate a Poly4D trajectory.
    speed_scale: simulates HLC time dilation (SPEED_SCALE).
      At speed_scale=0.5 the drone takes twice as long, so we sample
      the stored polynomial at t_stored = t_actual * speed_scale.

    Returns dict with arrays: t, x, y, z, vx, vy, vz, ax, ay, az,
                               seg_starts (global times of segment boundaries)
    """
    ts, xs, ys, zs = [], [], [], []
    vxs, vys, vzs = [], [], []
    axs, ays, azs = [], [], []
    seg_starts = []
    t_global = 0.0

    for row in traj:
        dur_stored = row[0]
        dur_actual = dur_stored / speed_scale   # actual flight duration

        cx   = row[1:9]
        cy   = row[9:17]
        cz   = row[17:25]

        seg_starts.append(t_global)

        for t_local_actual in np.linspace(0, dur_actual, pts_per_seg, endpoint=False):
            t_stored = t_local_actual * speed_scale

            xs.append(poly_eval(cx, t_stored))
            ys.append(poly_eval(cy, t_stored))
            zs.append(poly_eval(cz, t_stored))

            # velocity: dx/dt_actual = dx/dt_stored * speed_scale
            vxs.append(poly_deriv(cx, t_stored) * speed_scale)
            vys.append(poly_deriv(cy, t_stored) * speed_scale)
            vzs.append(poly_deriv(cz, t_stored) * speed_scale)

            # acceleration: d²x/dt_actual² = d²x/dt_stored² * speed_scale²
            axs.append(poly_deriv2(cx, t_stored) * speed_scale ** 2)
            ays.append(poly_deriv2(cy, t_stored) * speed_scale ** 2)
            azs.append(poly_deriv2(cz, t_stored) * speed_scale ** 2)

            ts.append(t_global + t_local_actual)

        t_global += dur_actual

    # Append final point
    row = traj[-1]
    dur_stored = row[0]
    cx, cy, cz = row[1:9], row[9:17], row[17:25]
    xs.append(poly_eval(cx, dur_stored))
    ys.append(poly_eval(cy, dur_stored))
    zs.append(poly_eval(cz, dur_stored))
    vxs.append(poly_deriv(cx, dur_stored) * speed_scale)
    vys.append(poly_deriv(cy, dur_stored) * speed_scale)
    vzs.append(poly_deriv(cz, dur_stored) * speed_scale)
    axs.append(poly_deriv2(cx, dur_stored) * speed_scale ** 2)
    ays.append(poly_deriv2(cy, dur_stored) * speed_scale ** 2)
    azs.append(poly_deriv2(cz, dur_stored) * speed_scale ** 2)
    ts.append(t_global)
    seg_starts.append(t_global)

    return dict(
        t=np.array(ts), x=np.array(xs), y=np.array(ys), z=np.array(zs),
        vx=np.array(vxs), vy=np.array(vys), vz=np.array(vzs),
        ax=np.array(axs), ay=np.array(ays), az=np.array(azs),
        seg_starts=np.array(seg_starts),
    )


# ---------------------------------------------------------------------------
# Compute waypoints from trajectory segment start/end positions
# ---------------------------------------------------------------------------

def waypoints_from_traj(traj):
    """Extract waypoint positions from each segment boundary."""
    pts = []
    for row in traj:
        cx = row[1:9]
        cy = row[9:17]
        pts.append((poly_eval(cx, 0.0), poly_eval(cy, 0.0)))
    # Last segment end
    row = traj[-1]
    pts.append((poly_eval(row[1:9], row[0]), poly_eval(row[9:17], row[0])))
    return np.array(pts)


# ---------------------------------------------------------------------------
# Evaluate trajectories
# ---------------------------------------------------------------------------

