fig8     = eval_trajectory(figure8_poly4d,     pts_per_seg=100, speed_scale=1.0)
our_fig8 = eval_trajectory(our_figure8_poly4d, pts_per_seg=100, speed_scale=1.0)

circle_wp   = waypoints_from_traj(circle_poly4d)
fig8_wp     = waypoints_from_traj(figure8_poly4d)
our_fig8_wp = waypoints_from_traj(our_figure8_poly4d)

circle_gap = np.hypot(circle['x'][-1] - circle['x'][0], circle['y'][-1] - circle['y'][0])
fig8_gap   = np.hypot(fig8['x'][-1]   - fig8['x'][0],   fig8['y'][-1]   - fig8['y'][0])
our_gap    = np.hypot(our_fig8['x'][-1]-our_fig8['x'][0],our_fig8['y'][-1]-our_fig8['y'][0])

# Trajectory error: interpolate our_fig8 onto fig8 time grid and compare
pos_err_x = our_fig8['x'] - fig8['x']
pos_err_y = our_fig8['y'] - fig8['y']
pos_err   = np.hypot(pos_err_x, pos_err_y)
rmse      = np.sqrt(np.mean(pos_err**2))
max_err   = pos_err.max()

print(f"Circle total duration (SPEED_SCALE={SPEED_SCALE}): {circle['t'][-1]:.2f} s")
print(f"Circle start: ({circle['x'][0]:.4f}, {circle['y'][0]:.4f})")
print(f"Circle end:   ({circle['x'][-1]:.4f}, {circle['y'][-1]:.4f})  gap={circle_gap*1000:.2f} mm")
