print(f"Prof's figure-8 total duration: {fig8['t'][-1]:.2f} s  |  gap={fig8_gap*1000:.2f} mm")
print(f"Our figure-8  total duration:   {our_fig8['t'][-1]:.2f} s  |  gap={our_gap*1000:.2f} mm")
print()
print(f"Figure-8 position comparison (same waypoints & durations):")
print(f"  RMSE  = {rmse*1000:.2f} mm")
print(f"  Max   = {max_err*1000:.2f} mm")
print(f"  (Both trajectories evaluated at same time grid)")
print()
print(f"Circle XY extents: x=[{circle['x'].min():.3f}, {circle['x'].max():.3f}]  y=[{circle['y'].min():.3f}, {circle['y'].max():.3f}] m")
print(f"Figure-8 XY extents: x=[{fig8['x'].min():.3f}, {fig8['x'].max():.3f}]  y=[{fig8['y'].min():.3f}, {fig8['y'].max():.3f}] m")

# ---------------------------------------------------------------------------
# Plot
# ---------------------------------------------------------------------------

fig = plt.figure(figsize=(18, 14))
fig.suptitle("Trajectory Validation — Circle & Figure-8 Poly4D", fontsize=14, fontweight='bold')
gs = gridspec.GridSpec(3, 3, figure=fig, hspace=0.45, wspace=0.38)

# ── XY paths ────────────────────────────────────────────────────────────────
ax_cxy = fig.add_subplot(gs[0, 0])
ax_cxy.set_title(f"Circle (r=0.30m, periodic, ×{SPEED_SCALE} speed)")
ax_cxy.plot(circle['x'], circle['y'], 'b-', linewidth=1.5, label='trajectory')
ax_cxy.scatter(circle_wp[:-1, 0], circle_wp[:-1, 1], c='blue', s=50, zorder=5, label='waypoints')
ax_cxy.plot(circle['x'][0], circle['y'][0], 'go', ms=10, label='start/end')
ax_cxy.set_xlabel('x (m)'); ax_cxy.set_ylabel('y (m)')
ax_cxy.set_aspect('equal'); ax_cxy.grid(True, alpha=0.3); ax_cxy.legend(fontsize=7)
ax_cxy.axhline(0, color='k', lw=0.5); ax_cxy.axvline(0, color='k', lw=0.5)
ax_cxy.text(0.02, 0.98, f"gap={circle_gap*1000:.2f} mm",
            transform=ax_cxy.transAxes, va='top', fontsize=8, color='darkgreen')

ax_fxy = fig.add_subplot(gs[0, 1])
ax_fxy.set_title("Figure-8 — prof's coefficients")
ax_fxy.plot(fig8['x'], fig8['y'], 'r-', linewidth=1.5, label="prof's")
ax_fxy.plot(our_fig8['x'], our_fig8['y'], 'b--', linewidth=1.2, alpha=0.8, label='ours (same WPs)')
ax_fxy.scatter(fig8_wp[:-1, 0], fig8_wp[:-1, 1], c='red', s=50, zorder=5)
ax_fxy.plot(fig8['x'][0], fig8['y'][0], 'go', ms=10, label='start/end')
ax_fxy.set_xlabel('x (m)'); ax_fxy.set_ylabel('y (m)')
ax_fxy.set_aspect('equal'); ax_fxy.grid(True, alpha=0.3); ax_fxy.legend(fontsize=7)
ax_fxy.axhline(0, color='k', lw=0.5); ax_fxy.axvline(0, color='k', lw=0.5)
ax_fxy.text(0.02, 0.98, f"RMSE={rmse*1000:.1f}mm  max={max_err*1000:.1f}mm",
            transform=ax_fxy.transAxes, va='top', fontsize=8, color='navy')

ax_err = fig.add_subplot(gs[0, 2])
ax_err.set_title("Figure-8 position error (ours − prof's)")
ax_err.plot(fig8['t'], pos_err * 1000, 'k-', linewidth=1.2)
ax_err.fill_between(fig8['t'], pos_err * 1000, alpha=0.2, color='purple')
for ts in fig8['seg_starts']:
    ax_err.axvline(ts, color='gray', lw=0.5, alpha=0.5)
ax_err.set_xlabel('t (s)'); ax_err.set_ylabel('|Δpos| (mm)')
ax_err.grid(True, alpha=0.3)
ax_err.text(0.98, 0.98, f"RMSE={rmse*1000:.1f}mm\nmax={max_err*1000:.1f}mm",
            transform=ax_err.transAxes, va='top', ha='right', fontsize=8)

# ── Position vs time ────────────────────────────────────────────────────────
ax_cp = fig.add_subplot(gs[1, 0])
ax_cp.set_title("Circle — position vs time")
ax_cp.plot(circle['t'], circle['x'], 'b-', label='x')
ax_cp.plot(circle['t'], circle['y'], 'b--', label='y')
for ts in circle['seg_starts']:
    ax_cp.axvline(ts, color='gray', lw=0.5, alpha=0.5)
ax_cp.set_xlabel('t (s)'); ax_cp.set_ylabel('position (m)')
ax_cp.legend(fontsize=8); ax_cp.grid(True, alpha=0.3)

ax_fp = fig.add_subplot(gs[1, 1])
ax_fp.set_title("Figure-8 — position vs time (prof vs ours)")
ax_fp.plot(fig8['t'], fig8['x'], 'r-', label="prof x")
ax_fp.plot(fig8['t'], fig8['y'], 'r--', label="prof y")
ax_fp.plot(our_fig8['t'], our_fig8['x'], 'b-', alpha=0.7, linewidth=1, label="our x")
ax_fp.plot(our_fig8['t'], our_fig8['y'], 'b--', alpha=0.7, linewidth=1, label="our y")
for ts in fig8['seg_starts']:
    ax_fp.axvline(ts, color='gray', lw=0.5, alpha=0.5)
ax_fp.set_xlabel('t (s)'); ax_fp.set_ylabel('position (m)')
ax_fp.legend(fontsize=7, ncol=2); ax_fp.grid(True, alpha=0.3)

ax_fv2_pos = fig.add_subplot(gs[1, 2])
ax_fv2_pos.set_title("Figure-8 — velocity vs time (prof vs ours)")
spd_prof = np.hypot(fig8['vx'], fig8['vy'])
spd_ours = np.hypot(our_fig8['vx'], our_fig8['vy'])
ax_fv2_pos.plot(fig8['t'], spd_prof, 'r-', label="prof |v|")
ax_fv2_pos.plot(our_fig8['t'], spd_ours, 'b--', alpha=0.8, label="ours |v|")
for ts in fig8['seg_starts']:
    ax_fv2_pos.axvline(ts, color='gray', lw=0.5, alpha=0.5)
ax_fv2_pos.set_xlabel('t (s)'); ax_fv2_pos.set_ylabel('speed (m/s)')
ax_fv2_pos.legend(fontsize=8); ax_fv2_pos.grid(True, alpha=0.3)

# ── Speed and acceleration magnitude ────────────────────────────────────────
c_speed = np.hypot(circle['vx'], circle['vy'])
f_speed = np.hypot(fig8['vx'], fig8['vy'])
c_acc   = np.hypot(circle['ax'], circle['ay'])
f_acc   = np.hypot(fig8['ax'], fig8['ay'])

ax_cv = fig.add_subplot(gs[2, 0])
ax_cv.set_title("Circle — speed & acceleration")
ax_cv2 = ax_cv.twinx()
l1, = ax_cv.plot(circle['t'], c_speed, 'b-', label='|v| (m/s)')
l2, = ax_cv2.plot(circle['t'], c_acc,  'b:', alpha=0.7, label='|a| (m/s²)')
for ts in circle['seg_starts']:
    ax_cv.axvline(ts, color='gray', lw=0.5, alpha=0.5)
ax_cv.set_xlabel('t (s)'); ax_cv.set_ylabel('speed (m/s)', color='b')
ax_cv2.set_ylabel('accel (m/s²)', color='b')
lines = [l1, l2]; ax_cv.legend(lines, [l.get_label() for l in lines], fontsize=8)
ax_cv.grid(True, alpha=0.3)

ax_fv = fig.add_subplot(gs[2, 1])
ax_fv.set_title("Prof's figure-8 — speed & accel")
ax_fv2 = ax_fv.twinx()
l3, = ax_fv.plot(fig8['t'], f_speed, 'r-', label='|v|')
l4, = ax_fv2.plot(fig8['t'], f_acc,  'r:', alpha=0.7, label='|a|')
for ts in fig8['seg_starts']:
    ax_fv.axvline(ts, color='gray', lw=0.5, alpha=0.5)
ax_fv.set_xlabel('t (s)'); ax_fv.set_ylabel('speed (m/s)', color='r')
ax_fv2.set_ylabel('accel (m/s²)', color='r')
lines = [l3, l4]; ax_fv.legend(lines, [l.get_label() for l in lines], fontsize=8)
ax_fv.grid(True, alpha=0.3)

ax_ov = fig.add_subplot(gs[2, 2])
ax_ov.set_title("Our figure-8 — speed & accel")
o_speed = np.hypot(our_fig8['vx'], our_fig8['vy'])
o_acc   = np.hypot(our_fig8['ax'], our_fig8['ay'])
ax_ov2 = ax_ov.twinx()
l5, = ax_ov.plot(our_fig8['t'], o_speed, 'b-', label='|v|')
l6, = ax_ov2.plot(our_fig8['t'], o_acc,  'b:', alpha=0.7, label='|a|')
for ts in our_fig8['seg_starts']:
    ax_ov.axvline(ts, color='gray', lw=0.5, alpha=0.5)
ax_ov.set_xlabel('t (s)'); ax_ov.set_ylabel('speed (m/s)', color='b')
ax_ov2.set_ylabel('accel (m/s²)', color='b')
lines = [l5, l6]; ax_ov.legend(lines, [l.get_label() for l in lines], fontsize=8)
ax_ov.grid(True, alpha=0.3)

plt.savefig('/tmp/trajectory_validation.png', dpi=150, bbox_inches='tight')
print("\nPlot saved to /tmp/trajectory_validation.png")
plt.show()
